L("إفريقيا: الخصائص الطبيعية والبشرية والقوة الاقتصادية (المعادن)", [95, 102],
  ["أن يعرف الطالب الخصائص الطبيعية والبشرية لقارة إفريقيا.", "أن يحدد الظواهر الطبيعية على الخريطة.", "أن يعرف مكامن الثروة المعدنية وأهميتها.", "أن يحدد مشاكل التعدين في إفريقيا."],
  "أسأل: لماذا تسمى إفريقيا «قارة المستقبل» رغم فقر كثير من شعوبها؟",
  "تقع إفريقيا وسط قارات العالم، يحدها المتوسط شمالا والمحيطان الهندي والأطلسي، يقسمها خط الاستواء ويمر بها المداران، مساحتها 30.2 مليون كلم² موزعة على 54 دولة. يغلب عليها الطابع الهضبي: هضبة شمال إفريقيا أو الصحراء الكبرى (أوسعها: الأطلس وتيبستي)، هضبة الحبشة (1500–3000 م، أعلاها، المنبع الموسمي للنيل)، هضبة البحيرات الاستوائية (المنبع الدائم للنيل، بحيرة فيكتوريا)، الهضبة الجنوبية (دراكنزبرج، أنهار الزمبيزي واللمبوبو والأورانج) ؛ وسهول ساحلية وداخلية، وجزر (مدغشقر، القمر). المناخ: استوائي (حرارة وأمطار طوال العام، غابات كثيفة)، مداري، صحراوي، متوسطي في الأطراف. السكان: تنوع عرقي ولغوي (العنصر الزنجي 75%)، نحو 1.5 مليار نسمة (2024)، يتركزون في السهول الفيضية والمرتفعات المعتدلة. المعادن: نحو 30% من احتياطي العالم، 85% من البلاتين و80% من الكروم ؛ النحاس والكوبالت (الكونغو الديمقراطية، زامبيا)، الماس (بوتسوانا، الكونغو، أنغولا، غانا، جنوب إفريقيا)، البلاتين (جنوب إفريقيا) ؛ ومشاكل التعدين: ضعف الاستكشاف والهياكل الإدارية ونقص الاستثمار والبنية التحتية (الطرق والسكك والكهرباء والمياه).",
  ["الموقع: يقسمها خط الاستواء، 30.2 مليون كلم²، 54 دولة.", "الهضاب: الصحراء الكبرى، الحبشة، البحيرات، الجنوبية.", "السكان: ~1.5 مليار (2024)، تنوع كبير.", "المعادن: 30% من الاحتياطي العالمي، 85% من البلاتين، 80% من الكروم.", "مشاكل التعدين: الاستكشاف، الاستثمار، البنية التحتية."],
  ("لماذا تبقى إمكانات إفريقيا المعدنية غير مستغلة بالكامل؟", "لانخفاض نشاط الاستكشاف بسبب ضعف الهياكل الإدارية ونقص الاستثمارات، ونقص البنية التحتية من طرق وسكك وكهرباء ومياه."),
  [S("أولا: الخصائص الطبيعية", ["الموقع: يحدها المتوسط شمالا، الهندي شرقا، الأطلسي غربا ؛ يقسمها خط الاستواء ويمر بها المداران.", "المساحة: 30.2 مليون كلم² ؛ 54 دولة."], table=[["الهضبة", "خصائصها"], ["شمال إفريقيا (الصحراء الكبرى)", "أوسعها، تضم الأطلس وتيبستي"], ["الحبشة (الإثيوبية)", "أعلاها 1500–3000 م، المنبع الموسمي للنيل"], ["البحيرات الاستوائية", "المنبع الدائم للنيل، بحيرة فيكتوريا"], ["الجنوبية", "دراكنزبرج، الزمبيزي واللمبوبو والأورانج"]]),
   S("المناخ والسكان", ["المناخ: استوائي (حرارة وأمطار دائمة، غابات)، مداري، صحراوي، متوسطي في الأطراف.", "السكان: ~1.5 مليار (2024)، العنصر الزنجي 75%، تنوع عرقي ولغوي وثقافي."]),
   S("ثانيا: المعادن", table=[["المعدن", "أهم الدول"], ["النحاس والكوبالت", "الكونغو الديمقراطية، زامبيا، جنوب إفريقيا، زيمبابوي"], ["الماس", "بوتسوانا، الكونغو الديمقراطية، أنغولا، غانا، جنوب إفريقيا"], ["البلاتين (85% عالميا)", "جنوب إفريقيا"], ["الكروم (80% عالميا)", "جنوب إفريقيا وزيمبابوي"]]),
   S("مشاكل التعدين", ["ضعف الاستكشاف والهياكل الإدارية ؛ نقص الاستثمارات ؛ نقص البنية التحتية (الطرق، السكك، الكهرباء، المياه)."])],
  apps=[("ما أعلى هضاب إفريقيا؟", "هضبة الحبشة (الإثيوبية)."), ("ما نسبة إفريقيا من احتياطي البلاتين العالمي؟", "حوالي 85%.")]),
