L("الاقتصاد الصيني: الأسس والمظاهر والمشاكل", [112, 118],
  ["أن يعرف الطالب الأسس العامة للاقتصاد الصيني.", "أن يميز مقومات الفلاحة والصناعة في الصين.", "أن يحدد المناطق الصناعية والفلاحية على الخريطة.", "أن يحدد مشاكل الاقتصاد الصيني."],
  "أسأل: ما الذي كتب «صنع في الصين» على أدواتك؟ وكيف صارت الصين مصنع العالم؟",
  "تقع الصين في شرق آسيا على المحيط الهادئ، مساحتها 9.5 مليون كلم²، يغلب عليها الطابع الجبلي والهضبي ولا تمثل السهول إلا 20% (سهل منشوريا، السهل الشمالي الكبير، سهول هوانغ هو ويانغ تسي كيانغ) ؛ تتوفر على الفحم والبترول والغاز والمعادن، وسكانها أكثر من مليار و394 مليون نسمة (2020) سوقا استهلاكية ويدا عاملة ؛ وكان للإصلاحات الاقتصادية ثم الانفتاح دور حاسم: جلب الاستثمارات والتكنولوجيا الغربية وتشجيع الصناعات الموجهة للتصدير. الفلاحة في الواجهة الشرقية: القمح شمالا، القمح والشاي والقطن في الوسط، الأرز والشاي وقصب السكر جنوبا ؛ والغرب مراع وصحار. الصناعة: من الصناعات الأساسية إلى العالية التكنولوجيا (الإلكترونية والفضائية والنووية)، وتحتل الصين المرتبة الأولى عالميا في المنسوجات (40%) والصلب (53%) والإلكترونيات (50%) والسيارات (33%) والطاقة المتجددة (70%) ؛ ومراكزها الكبرى: شنغهاي، كوانغ زو. مشاكلها: اقتصادية (منافسة الأقطاب العالمية وقيود الدول المتقدمة)، اجتماعية (ضعف التنمية البشرية مقارنة بالنمو، الشيخوخة، تفاوت المدن والأرياف، البطالة والفقر والهجرة)، طبيعية وبيئية (غلبة المرتفعات، جفاف الغرب، فيضانات وأعاصير الجنوب، تلوث المناطق الصناعية).",
  ["الموقع: شرق آسيا، 9.5 مليون كلم²، سهول 20% فقط.", "السكان: >1.394 مليار (2020).", "الإصلاح والانفتاح: الاستثمار والتكنولوجيا والتصدير.", "الصناعة: الأولى عالميا في المنسوجات والصلب والإلكترونيات والسيارات والطاقة المتجددة.", "المشاكل: المنافسة، الشيخوخة، التفاوت، الكوارث والتلوث."],
  ("ما دور الإصلاحات والانفتاح في قوة الاقتصاد الصيني؟", "مكنت من جلب الاستثمارات والتكنولوجيا الغربية وتشجيع الصناعات الموجهة للتصدير، فصارت الصين منافسا لكبريات الاقتصادات."),
  [S("1. الأسس العامة", table=[["المؤهلات", "عناصرها"], ["الطبيعية", "شرق آسيا على الهادئ، 9.5 مليون كلم²، جبال وهضاب، سهول 20%، الفحم والبترول والغاز والمعادن"], ["البشرية", ">1.394 مليار نسمة (2020): يد عاملة وسوق استهلاكية"], ["التنظيمية", "الإصلاحات ثم الانفتاح: الاستثمار الأجنبي، التكنولوجيا، التصدير"]]),
   S("2. الفلاحة", ["الواجهة الشرقية: القمح شمالا ؛ القمح والشاي والقطن وسطا ؛ الأرز والشاي وقصب السكر جنوبا.", "الغرب: مراع وصحار وغابات."]),
   S("3. الصناعة (2023–2024)", table=[["الصناعة", "الحصة العالمية", "الرتبة"], ["المنسوجات", "40%", "1"], ["الصلب", "53%", "1"], ["الإلكترونيات", "50%", "1"], ["السيارات", "33%", "1"], ["الطاقة المتجددة", "70%", "1"]]),
   S("4. المشاكل", ["اقتصادية: منافسة الأقطاب العالمية وقيود الدول المتقدمة.", "اجتماعية: ضعف التنمية البشرية، الشيخوخة، تفاوت المدن والأرياف.", "طبيعية وبيئية: المرتفعات، جفاف الغرب، فيضانات وأعاصير الجنوب، التلوث."])],
  apps=[("ما نسبة السهول من مساحة الصين؟", "حوالي 20%."), ("اذكر صناعتين تحتل فيهما الصين المرتبة الأولى عالميا.", "الصلب (53%) والإلكترونيات (50%).")]),
